+static void btusb_raw_vendor_cmd_remove_locked(struct btusb_data *data,
+					       struct btusb_raw_vendor_cmd *cmd,
+					       struct list_head *cmds,
+					       bool *queue)
+{
+	list_move_tail(&cmd->list, cmds);
+	data->raw_vendor_cmd_count--;
