+	/* disable bit-bang mode again */
+	val = iproc_i2c_rd_reg(iproc_i2c, CFG_OFFSET);
+	val &= ~BIT(CFG_BITBANG_EN_SHIFT);
+	iproc_i2c_wr_reg(iproc_i2c, CFG_OFFSET, val);
+	usleep_range(10, 15);
