@@ -520,7 +580,9 @@ int main(int argc, char **argv)
 	fd = tun_alloc(&dev, tun_name);
 	assert(fd >= 0);
 
-	vdev_info_init(&dev, features);
+	vdev_info_init(&dev, features, features_array);
